local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[402703]=b({e[9034],402703,7,54,164,"「次はお前さんの番だ。ほら、靴脱いで体重計に乗ってくれ。面倒かもしれないけど、毎年の健康診断は大事だぞ。身長と体重は秘密にしてやるから、心配するなって。」",200027,2,"deco/character/402703",1902,783,382,520,685,2917,3285,528,685,2901,1049,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[402704]=b({e[23034],402704,3,27,165,"「ここまで追い詰められたのは初めてだ……なんたる不覚。しかし、人狼の誇りにかけて誓おう。我が剣が折れ、骨が粉々になるまで、何人たりともここは通さん！」",200027,2,"deco/character/402704",false,false,false,false,false,false,false,false,false,false,false,"0,-220,1","-280,0,1","-260,0,1",2191,938,380,722,76,2821,2675,722,627,2821,1261,1,7214,5000,3937,5859,8000,11500,6000,8000,10000,8000,8000,false,false,0},h)g[402705]=b({e[21034],402705,13,28,166,"「肉体の休息は精神の休息。麻雀で負けて落ち込んでる時こそ、こういう癒しを心と体で実感できるってもんだ。もちろん、こうしてお前さんと遠出してること自体が一番嬉しいんだけどな。いや〜、癒されるな〜！　はははっ！」",200027,2,"deco/character/402705",false,false,false,false,false,false,false,"1",false,false,false,"150,-220,1",1918,868,399,752,175,2818,2789,752,567,2818,1261,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[402801]=b({e[32057],402801,false,85,167,false,200028,false,"deco/character/tengbenqiluo",302002,60,1,false,false,false,65,false,false,false,false,false,false,false,false,false,"-100,0,1",false,false,false,false,"-60,0,1","-90,0,1","tengbenqiluo"},h)g[402802]=b({e[11057],402802,1,4,168,"「こっちみて〜！ はいチーズっ！\n……ヤバっ、初デートの記念写真、超盛れてんじゃん！」",200028,1,"deco/character/tengbenqiluo_0",302002,60,"tengbenqiluo_0"},h)g[402803]=b({e[18057],402803,5,42,169,"「ジャジャーン！　ピッチピチの新春ギャル登場～！　ギャルにかかれば、伝統的なヤツだって全然イマドキでいけるし！」",200028,2,"deco/character/tengbenqiluo_YD",false,false,false,1,false,false,false,false,"2020-12-30 05:00:00+08","tengbenqiluo_yd"},h)g[402804]=b({e[23057],402804,9,86,170,"「一局どぉ？　はぁ？　確かに30分前に寝るっつったけど、おやすみ～って言ってからの夜更かしはキホンっしょ？　だからさぁ、麻雀しよーよ、ね？」",200028,2,"deco/character/tengbenqiluo_SY",false,false,1,false,false,false,false,"1",false,false,false,"0,-140,1","-362,0,1","-370,0,1","tengbenqiluo_sy"},h)g[402805]=b({e[24057],402805,13,28,171,"「なにそんなとこで突っ立ってんの？　疲れてる時の温泉より惹かれるものがあるとか？　へへっ、一日ずっと付き合ってもらったんだし、これくらいのご褒美はちゃんと用意したげるって。」",200028,2,"deco/character/tengbenqiluo_WQ",false,false,false,false,false,false,false,"1",false,false,"-150,0,1","200,-350,1","-100,0,1","-100,0,1","-140,0,1","tengbenqiluo_wq"},h)g[402806]=b({e[17057],402806,18,9,172,"「もーマジおっそーい！\nモタモタしてるうちに、メイク直しまで済んじゃったんだけど！ 遅れた分のデートの時間、今から取り返すよ！\nんじゃ飛ばすから、しっかり腰んとこつかまってて！ わかった！？」",200028,2,"deco/character/tengbenqiluo_kxj",false,false,false,false,false,false,false,"","tengbenqiluo_kxj"},h)g[402901]=b({e[46057],402901,false,87,173,false,200029,false,"deco/character/huiyeji",302002,60,1,false,false,false,81,"1",false,false,false,false,false,false,false,"0,-60,1.05","-60,120,1.02","-50,100,1",false,false,false,"-100,100,1.02","-40,100,1",false,false,false,1925,986,400,1069,504,2161,2590,1069,685,2161,1261,"huiyeji"},h)g[402902]=b({e[12034],402902,1,4,174,"「わらわに奉仕したいと言う者は、この世にいくらでもおる。\nしかし、やはり汝こそ、わらわが最も好む凡人じゃな。\n今日からは、わらわの世界征服軍の総大将になってもらうのじゃ〜！」",200029,1,"deco/character/huiyeji_0",302002,60,1,1910,959,400,702,464,3134,2869,818,658,2902,1261,false,false,false,false,false,false,false,false,false,false,false,false,"huiyeji_0"},h)g[402903]=b({e[12034],402903,4,78,175,"「凡人の体力はそれっぽっちか？　早う付いて参れ！　ぐひひ……！　今宵この神様が、クリスマスプレゼントを心待ちにしておる人間どもに、しかと『サプライズ』を届けてやるのじゃ～！」",200029,2,"deco/character/huiyeji_SD",false,false,1,1652,1053,385,702,261,2692,2864,702,745,2692,1261,false,false,false,false,false,false,false,false,false,false,false,false,"huiyeji_sd"},h)g[402904]=b({e[21034],402904,6,88,176,"「金屋貯嬌という熟語の成り立ちを聞いたことはあるか？　汝が願うなら、宝石で造った宮殿に妾を囲って独り占めすること程度、叶えてやっても……ぐひひ、妾はあえて許そうぞ」",200029,2,"deco/character/402904",false,false,1,false,false,false,false,false,false,false,false,"480,-300,1",1960,939,361,459,false,2570,3273,459,619,2570,1261,1,6858,5000,3990,7032,4000,4666,8333,4333,8000,false,4000,"huiyeji_cj",false,0},h)g[402905]=b({e[12034],402905,13,89,177,"「無礼者、わらわの貸切温泉に勝手に入るでない！　……何じゃ、当然ここら一帯の温泉は全部わらわの貸切りじゃ！　ほれ、あっちの小さい池なら入ってよいぞ。そうじゃ、一番小さいやつじゃ。さっさと行かんか！」",200029,2,"deco/character/huiyeji_WQ",false,false,1,2053,892,388,498,193,2879,3449,498,585,2879,1261,false,false,false,false,false,false,false,false,false,false,false,false,"huiyeji_wq"},h)